// Court abbreviation to PACER domain mapping
const courtMappings = {
  "S.D.N.Y.": "nysd",      // Southern District of New York
  "E.D.N.Y.": "nyed",      // Eastern District of New York
  "S.D. Tex.": "txsd",     // Southern District of Texas
  "N.D. Cal.": "cand",     // Northern District of California
  "C.D. Cal.": "cacd",     // Central District of California
  "S.D. Cal.": "casd",     // Southern District of California
  "E.D. Cal.": "caed",     // Eastern District of California
  "D. Del.": "ded",        // District of Delaware
  "D.N.J.": "njd",         // District of New Jersey
  "E.D. Va.": "vaed",      // Eastern District of Virginia
  "N.D. Ill.": "ilnd",     // Northern District of Illinois
  "S.D. Fla.": "flsd",     // Southern District of Florida
  "D. Mass.": "mad",       // District of Massachusetts
  "E.D. Pa.": "paed",      // Eastern District of Pennsylvania
  "D.D.C.": "dcd",         // District of Columbia
  // Add more courts as needed
};

// Get input from Google Sheets trigger
const caseNumber = $input.item.json.case_number;
const court = $input.item.json.court;
const assignedAttorney = $input.item.json.assigned_attorney;
const caseType = $input.item.json.case_type;
const dateAdded = $input.item.json.date_added;

// Validate case number format
// Federal case format: {division}:{year}-{case_type}-{number}
// Example: 1:23-cv-01234
const caseRegex = /^\d+:\d{2}-[a-z]{2,3}-\d{5}$/i;

if (!caseNumber || !caseRegex.test(caseNumber)) {
  throw new Error(`Invalid case number format: "${caseNumber}". Expected format: 1:23-cv-01234`);
}

// Map court to PACER domain
const pacerDomain = courtMappings[court];

if (!pacerDomain) {
  throw new Error(`Unsupported court: "${court}". Supported courts: ${Object.keys(courtMappings).join(', ')}`);
}

// Construct RSS URL
const rssUrl = `https://ecf.${pacerDomain}.uscourts.gov/cgi-bin/rss_outside.pl?${caseNumber}`;

// Return data ready for database insertion
return {
  case_number: caseNumber,
  court: court,
  assigned_attorney: assignedAttorney || null,
  case_type: caseType || null,
  rss_url: rssUrl,
  status: 'Active',
  date_added: dateAdded
};

// Parse each RSS item to extract structured data
const item = $input.item.json;

// Extract case number and name from title
const title = item.title || '';
const caseNumberMatch = title.match(/^(\d+:\d{2}-[a-z]{2,3}-\d{5})/i);
const caseNumber = caseNumberMatch ? caseNumberMatch[1] : null;
const caseName = title.replace(/^(\d+:\d{2}-[a-z]{2,3}-\d{5})\s*/i, '').trim();

// Extract description
const description = item.description || '';

// Extract entry number (visible docket number)
const entryNumberMatch = description.match(/>(\d+)<\/a>/);
const entryNumber = entryNumberMatch ? parseInt(entryNumberMatch[1]) : null;

// Extract filing type from brackets
const filingTypeMatch = description.match(/\[(.*?)\]/);
const filingType = filingTypeMatch ? filingTypeMatch[1] : 'Unknown';

// Parse date
const pubDate = item.pubDate || '';
const entryDate = pubDate ? new Date(pubDate).toISOString().split('T')[0] : null;

// Clean description
const cleanDescription = description
  .replace(/<[^>]*>/g, '')
  .replace(/&amp;/g, '&')
  .replace(/&#x3C;/g, '<')
  .replace(/&#x3E;/g, '>')
  .replace(/&#x22;/g, '"')
  .replace(/&#x27;/g, "'")
  .trim();

return {
  case_number: caseNumber,
  case_name: caseName,
  entry_number: entryNumber,
  filing_type: filingType,
  description: cleanDescription,
  entry_date: entryDate,
  docket_link: item.link || null,
  court: 'N.D. Cal.',
  raw_pub_date: pubDate
};

const currentEntry = $input.item.json;

// Get list of monitored case numbers from Node 2
const monitoredCasesData = $('Get Monitored Cases').all();
const monitoredCaseNumbers = monitoredCasesData.map(item => item.json.case_number);

// Also create a map for quick lookup of attorney assignments
const caseToAttorney = {};
monitoredCasesData.forEach(item => {
  caseToAttorney[item.json.case_number] = item.json.assigned_attorney;
});

// Check if this entry is for a monitored case
if (!monitoredCaseNumbers.includes(currentEntry.case_number)) {
  // Not a monitored case - stop processing this item
  return null;
}

// This IS a monitored case - add attorney info and pass through
return {
  ...currentEntry,
  assigned_attorney: caseToAttorney[currentEntry.case_number]
};
